def naming_fixture():
    names = ('config', 'configCanonicalPayload', 'writeConfigPreserving', 'm_configCanonicalPayload',
             'signals', 'Q_OBJECT', 'Q_EMIT', 'qobject_cast', '__proto__')
    groups = tuple((name, [(1, field, 3) for field in names])
                   for name in ('StaticType', 'StaticEndpoint', 'QObject', 'Qt'))
    return fixture.descriptor(groups=(groups, (), ()))


class ConfiguratorGeneratorTests(unittest.TestCase):
    def test_default_sealed_bytes(self):
        for name, expected in BASELINE.items():
            with self.subTest(fixture=name):
                output = qml.generate(load_schema(fixture.fixture(name)))
                self.assertEqual({path: hashlib.sha256(text.encode('utf-8')).hexdigest()
                                  for path, text in output.items()}, expected)

    def test_opt_in_only_changes_owned_seams(self):
        schema = load_schema(fixture.fixture('mixed'))
        ordinary = qml.generate(schema)
        extended = generate_qml_configurator(schema)
        self.assertEqual(set(extended.files), set(ordinary) | {'qml/ConfiguratorBinding.hpp'})
        for name in ('QmlValues.hpp', 'QmlInput.hpp', 'QmlRpcAdapter.hpp', 'DeviceClientAdapter.hpp'):
            self.assertEqual(extended.files['qml/' + name], ordinary['qml/' + name])
        mapping = extended.symbol_mapping
        self.assertEqual(mapping, qml.symbol_mapping(schema, configurator=True))
        self.assertNotIn('canonicalPayload', ordinary['qml/DeviceApi.hpp'])

    def test_added_families_never_collide(self):
        schema = load_schema(naming_fixture(), 'naming_api')
        groups = qml.layout(schema, configurator=True)
        for group in groups:
            names = set(qml.GROUP_RESERVED)
            for endpoint, stem in group['endpoints']:
                family = qml._family(stem, endpoint.category, configurator=True)
                self.assertTrue(family.isdisjoint(names), stem)
                names.update(family)
        # The same symbols are the manifest contract used by the generated callbacks.
        self.assertEqual(generate_qml_configurator(schema).symbol_mapping,
                         qml.symbol_mapping(schema, configurator=True))


